export function prioritizeUpgrades(upgrades) {
  return upgrades.sort((a, b) => {
    const impactA = a.systemicImpact * a.capabilityGap;
    const impactB = b.systemicImpact * b.capabilityGap;
    return impactB - impactA;
  });
}